import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"自定义主题","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/customization/themes.md","filePath":"zh/kimi-code-cli/customization/themes.md"}`),a={name:`kimi-code-cli/customization/themes.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="自定义主题" tabindex="-1">自定义主题 <a class="header-anchor" href="#自定义主题" aria-label="Permalink to “自定义主题”">​</a></h1><p>Kimi Code CLI 可以使用内置配色，也可以使用自定义 JSON 主题文件。自定义文件放在主题目录下，会和内置选项一起出现在 <code>/theme</code> 里。</p><h2 id="内置颜色-token" tabindex="-1">内置颜色 token <a class="header-anchor" href="#内置颜色-token" aria-label="Permalink to “内置颜色 token”">​</a></h2><p>自定义主题可以覆盖下面这些 token。<code>dark</code> 和 <code>light</code> 两列展示内置值；<code>auto</code> 会在启动时解析为其中一个调色板，如果无法检测终端背景，则回退到 <code>dark</code>。</p><table tabindex="0"><thead><tr><th>Token</th><th><code>dark</code></th><th><code>light</code></th><th>控制什么</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>#4FA8FF</code></td><td><code>#1565C0</code></td><td>最常用色。链接、行内代码、几乎所有对话框的选中项、编辑器聚焦边框、Plan/运行中徽章、spinner</td></tr><tr><td><code>accent</code></td><td><code>#5BC0BE</code></td><td><code>#00838F</code></td><td>次级强调。审批 <code>▶</code> 前缀、设备码框、图片占位、BTW/队列面板、注册表导入</td></tr><tr><td><code>text</code></td><td><code>#E0E0E0</code></td><td><code>#1A1A1A</code></td><td>正文。对话框正文、todo 标题、footer 模型名、Markdown 标题、助手/工具消息子弹头、列表符号</td></tr><tr><td><code>textStrong</code></td><td><code>#F5F5F5</code></td><td><code>#1A1A1A</code></td><td>加粗强调文字。输入类对话框、状态消息</td></tr><tr><td><code>textDim</code></td><td><code>#888888</code></td><td><code>#454545</code></td><td>次级、变暗文字。思考、提示、描述、已完成 todo、Markdown 引用、footer 状态栏</td></tr><tr><td><code>textMuted</code></td><td><code>#6B6B6B</code></td><td><code>#5F5F5F</code></td><td>最浅文字。计数、滚动信息、描述、Markdown 链接 URL、代码块边框</td></tr><tr><td><code>border</code></td><td><code>#5A5A5A</code></td><td><code>#737373</code></td><td>面板与编辑器的普通边框、Markdown 分隔线</td></tr><tr><td><code>borderFocus</code></td><td><code>#E8A838</code></td><td><code>#92660A</code></td><td>聚焦/注意边框，目前仅审批面板使用</td></tr><tr><td><code>success</code></td><td><code>#4EC87E</code></td><td><code>#0E7A38</code></td><td>成功态。<code>✓</code>、已启用、完成</td></tr><tr><td><code>warning</code></td><td><code>#E8A838</code></td><td><code>#92660A</code></td><td>警告态。auto/yolo 徽章、过期标记、Plan 模式提示</td></tr><tr><td><code>error</code></td><td><code>#E85454</code></td><td><code>#B91C1C</code></td><td>错误态。错误信息、失败的工具输出</td></tr><tr><td><code>diffAdded</code></td><td><code>#4EC87E</code></td><td><code>#0E7A38</code></td><td>diff 新增行</td></tr><tr><td><code>diffRemoved</code></td><td><code>#E85454</code></td><td><code>#B91C1C</code></td><td>diff 删除行</td></tr><tr><td><code>diffAddedStrong</code></td><td><code>#7AD99B</code></td><td><code>#0E7A38</code></td><td>diff 行内改动的新增词（加粗高亮）</td></tr><tr><td><code>diffRemovedStrong</code></td><td><code>#F08585</code></td><td><code>#B91C1C</code></td><td>diff 行内改动的删除词（加粗高亮）</td></tr><tr><td><code>diffGutter</code></td><td><code>#6B6B6B</code></td><td><code>#737373</code></td><td>diff 行号槽</td></tr><tr><td><code>diffMeta</code></td><td><code>#888888</code></td><td><code>#5F5F5F</code></td><td>diff 元信息 / hunk 头</td></tr><tr><td><code>roleUser</code></td><td><code>#FFCB6B</code></td><td><code>#9A4A00</code></td><td>用户消息的子弹头与文字、技能激活名</td></tr><tr><td><code>shellMode</code></td><td><code>#BD93F9</code></td><td><code>#7C3AED</code></td><td>Shell 模式（<code>!</code>）的提示符、编辑器边框，以及回显的 <code>$ 命令</code> 行</td></tr></tbody></table><h2 id="使用-custom-theme-skill" tabindex="-1">使用 custom-theme skill <a class="header-anchor" href="#使用-custom-theme-skill" aria-label="Permalink to “使用 custom-theme skill”">​</a></h2><p>你不需要手写 JSON。运行内置 <code>/custom-theme [附加文本]</code> skill 命令进入自定义主题流程；这个 skill 可以帮你选颜色，把文件写到 <code>~/.kimi-code/themes/</code>，校验十六进制色值，并告诉你如何应用。</p><p>调用示例：</p><ul><li><code>/custom-theme Create a warm dark theme with amber accents.</code></li><li><code>/custom-theme Make a light theme based on Solarized, but keep errors easy to see.</code></li><li><code>/custom-theme Tweak my ember theme so diffs have higher contrast.</code></li></ul><p>激活后，skill 通常会先问你想用浅色还是深色基准、偏好的风格或调色板，以及是否有必须包含的精确颜色。如果你用它编辑已有主题，请确保它先读取并备份文件，再覆盖写入。</p><h2 id="创建一个主题" tabindex="-1">创建一个主题 <a class="header-anchor" href="#创建一个主题" aria-label="Permalink to “创建一个主题”">​</a></h2><p>在主题目录下新建一个 <code>.json</code> 文件即可。主题目录是：</p><ul><li><code>~/.kimi-code/themes/</code></li><li>如果设置了 <code>KIMI_CODE_HOME</code> 环境变量，则是 <code>$KIMI_CODE_HOME/themes/</code></li></ul><p>目录不存在就自己建一个。<strong>文件名就是主题名</strong>：<code>ember.json</code> 会在 <code>/theme</code> 里显示为 <code>Custom: ember</code>。</p><p>一个最小的主题只需要写你想改的颜色，其余自动沿用<strong>基准调色板</strong>（默认是 <code>dark</code>）：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ember&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;colors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;primary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#83A598&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;accent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#FE8019&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>字段说明：</p><ul><li><code>name</code>（必填）：主题的标识名。</li><li><code>displayName</code>（可选）：人类可读的名字。</li><li><code>base</code>（可选）：未指定的 token 沿用哪个内置调色板——<code>&quot;dark&quot;</code>（默认）或 <code>&quot;light&quot;</code>。做<strong>浅色</strong>主题时设为 <code>&quot;base&quot;: &quot;light&quot;</code>，这样你没写的 token 在浅色背景上仍然可读（否则会回退到 dark 调色板）。</li><li><code>colors</code>（可选）：要覆盖的颜色 token，值是 6 位十六进制色值（如 <code>#FE8019</code>）。</li></ul><p>使用 <a href="#内置颜色-token">内置颜色 token</a> 里的 token 名。没有写到的 token 会自动回退到所选基准调色板的对应值，所以你完全可以只覆盖一部分：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;just-blue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;colors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;primary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#3B82F6&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;roleUser&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#3B82F6&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="选用主题" tabindex="-1">选用主题 <a class="header-anchor" href="#选用主题" aria-label="Permalink to “选用主题”">​</a></h2><p>两种方式：</p><ol><li><p><strong><code>/theme</code> 命令</strong>（推荐）：打开主题选择器，自定义主题会以 <code>Custom: &lt;文件名&gt;</code> 出现。选择器<strong>每次打开都会重新扫描主题目录</strong>，所以你新加的主题文件<strong>无需重启</strong>就能看到。</p></li><li><p><strong><code>tui.toml</code></strong>：把 <code>theme</code> 设成你的主题名：</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># ~/.kimi-code/tui.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">theme = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ember&quot;</span></span></code></pre></div></li></ol><h2 id="出错时会怎样" tabindex="-1">出错时会怎样 <a class="header-anchor" href="#出错时会怎样" aria-label="Permalink to “出错时会怎样”">​</a></h2><p>自定义主题的设计原则是&quot;尽量别打断你&quot;：</p><ul><li><strong>某个色值不合法</strong>（不是 <code>#</code> 加 6 位十六进制）：静默跳过这一项，并回退到所选基准调色板，其余颜色照常生效。</li><li><strong>写了无法识别的 token</strong>：忽略，不影响其它颜色。</li><li><strong>自定义主题文件不存在或 JSON 损坏</strong>：静默回退到内置 <code>dark</code> 调色板，不会再尝试 <code>auto</code>。</li></ul><h2 id="编辑正在使用的主题" tabindex="-1">编辑正在使用的主题 <a class="header-anchor" href="#编辑正在使用的主题" aria-label="Permalink to “编辑正在使用的主题”">​</a></h2><p>如果你修改的是<strong>当前正在生效</strong>的那个主题文件，改动不会自动重新加载。让新颜色生效有两种办法：</p><ul><li>运行 <code>/reload-tui</code>——它会重新读取 <code>tui.toml</code> 并重新应用当前主题（包括重新读取主题文件）；</li><li>或者在 <code>/theme</code> 里先切到另一个主题，再切回来。</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>在 <code>/theme</code> 里<strong>重新选中同一个主题</strong>不会触发重载（只会提示 “Theme unchanged”）。要重载已激活主题的改动，用上面两种办法之一。</p></div>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};